TWComponent.script:
tw.local.odcRequest.stepLog.role     = tw.local.role;
tw.local.odcRequest.stepLog.userName = tw.system.user.name;
tw.local.odcRequest.stepLog.endTime  = new tw.object.Date();
tw.local.odcRequest.History.insertIntoList(tw.local.odcRequest.History.listLength, tw.local.odcRequest.stepLog);

